#[path = "solution.rs"]
mod solution;

use solution::{parse_packet, parse_text_packet, ParseError, Verb};

#[test]
fn parses_binary_packet_and_preserves_attributes_and_body() {
    let input = b"WRITE /items/7\nkind:text\nkind:duplicate\nempty:\ncolon:a:b:c\n\n\x00\xffbody\n\nend";
    let packet = match parse_packet(input) {
        Ok(packet) => packet,
        Err(_) => panic!("valid packet was rejected"),
    };

    assert!(matches!(packet.verb, Verb::Write));
    assert_eq!(packet.route, "/items/7");
    assert_eq!(packet.attributes.len(), 4);
    assert_eq!(packet.attributes[0], (String::from("kind"), String::from("text")));
    assert_eq!(packet.attributes[1], (String::from("kind"), String::from("duplicate")));
    assert_eq!(packet.attributes[2], (String::from("empty"), String::new()));
    assert_eq!(packet.attributes[3], (String::from("colon"), String::from("a:b:c")));
    assert_eq!(packet.payload, b"\x00\xffbody\n\nend");
}

#[test]
fn parses_each_verb_and_empty_payload() {
    let cases: &[(&[u8], fn(&Verb) -> bool)] = &[
        (b"READ /r\n\n", |verb| matches!(verb, Verb::Read)),
        (b"WRITE /w\n\n", |verb| matches!(verb, Verb::Write)),
        (b"REPLACE /p\n\n", |verb| matches!(verb, Verb::Replace)),
        (b"REMOVE /d\n\n", |verb| matches!(verb, Verb::Remove)),
    ];

    for (input, expected_verb) in cases {
        let packet = parse_packet(input).unwrap_or_else(|_| panic!("valid verb rejected"));
        assert!(expected_verb(&packet.verb));
        assert!(packet.attributes.is_empty());
        assert!(packet.payload.is_empty());
    }
}

#[test]
fn text_parser_preserves_unicode_and_blank_lines_in_body() {
    let input = "REPLACE /café\nlang:日本語\n\nfirst\n\nthird".as_bytes();
    let packet = parse_text_packet(input).unwrap_or_else(|_| panic!("valid text packet rejected"));
    assert!(matches!(packet.verb, Verb::Replace));
    assert_eq!(packet.route, "/café");
    assert_eq!(packet.attributes, vec![(String::from("lang"), String::from("日本語"))]);
    assert_eq!(packet.payload, "first\n\nthird");
}

#[test]
fn reports_missing_separator() {
    assert!(matches!(parse_packet(b"READ /route\nname:value"), Err(ParseError::MissingSeparator)));
    assert!(matches!(parse_packet(b""), Err(ParseError::MissingSeparator)));
}

#[test]
fn rejects_non_utf8_header() {
    let input = b"READ /\nbad:\xff\n\nbody";
    assert!(matches!(parse_packet(input), Err(ParseError::InvalidHeaderUtf8)));
}

#[test]
fn rejects_invalid_start_lines() {
    for input in [
        &b"READ\n\n"[..],
        &b"READ \n\n"[..],
        &b" /route\n\n"[..],
        &b"READ  /route\n\n"[..],
        &b"READ /route extra\n\n"[..],
        &b"READ\t/route\n\n"[..],
    ] {
        assert!(matches!(parse_packet(input), Err(ParseError::InvalidStartLine)));
    }
}

#[test]
fn rejects_unknown_verb() {
    assert!(matches!(parse_packet(b"PATCH /route\n\n"), Err(ParseError::UnknownVerb)));
}

#[test]
fn rejects_attributes_without_a_nonempty_name() {
    assert!(matches!(parse_packet(b"READ /\nmissing-colon\n\n"), Err(ParseError::InvalidAttribute)));
    assert!(matches!(parse_packet(b"READ /\n:value\n\n"), Err(ParseError::InvalidAttribute)));
}

#[test]
fn text_parser_rejects_non_utf8_body_but_binary_parser_accepts_it() {
    let input = b"READ /raw\n\n\xff\xfe";
    assert!(parse_packet(input).is_ok());
    assert!(matches!(parse_text_packet(input), Err(ParseError::InvalidBodyUtf8)));
}

#[test]
fn parsed_packet_owns_copies_and_does_not_alias_input() {
    let mut input = b"REMOVE /owned\na:b\n\npayload".to_vec();
    let packet = parse_packet(&input).unwrap_or_else(|_| panic!("valid packet rejected"));
    input.fill(b'x');

    assert_eq!(packet.route, "/owned");
    assert_eq!(packet.attributes[0], (String::from("a"), String::from("b")));
    assert_eq!(packet.payload, b"payload");
}

